package com.vandorlabs.neoforge.navigation;
import com.mojang.serialization.MapCodec;
import com.vandorlabs.navigation.NavigationLayout;
import com.vandorlabs.neoforge.NativeConfigurationAccess;
import net.minecraft.core.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.*;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.*;
public final class NativeNavigationTableBlock extends BaseEntityBlock {
 public static final DirectionProperty FACING=BlockStateProperties.HORIZONTAL_FACING;public static final IntegerProperty CONNECTIONS=IntegerProperty.create("connections",0,15);public final NavigationLayout.Kind kind;
 public NativeNavigationTableBlock(Properties properties,NavigationLayout.Kind kind){super(properties);this.kind=kind;registerDefaultState(stateDefinition.any().setValue(FACING,Direction.NORTH).setValue(CONNECTIONS,0));}
 @Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState> b){b.add(FACING,CONNECTIONS);}@Override public BlockState getStateForPlacement(BlockPlaceContext c){return defaultBlockState().setValue(FACING,c.getHorizontalDirection().getOpposite());}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return new NativeNavigationTableEntity(p,s);}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return level.isClientSide?null:createTickerHelper(type,NativeNavigationTableBindings.ENTITY,(world,pos,current,tile)->{if(tile.formed()&&tile.ownsReader()&&!com.vandorlabs.neoforge.gear.NativeGearHolds.reserved(world,pos)&&!com.vandorlabs.neoforge.transfer.NativeTransferHolds.reserved(world,pos)&&world.getGameTime()%20==Math.floorMod(pos.asLong(),20))NativeNavigationTableHooks.TABLE.recordSources(tile);});}
 @Override protected RenderShape getRenderShape(BlockState s){return RenderShape.MODEL;}@Override protected VoxelShape getShape(BlockState s,BlockGetter l,BlockPos p,CollisionContext c){return Block.box(0,0,0,16,14,16);}
 @Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState old,boolean moving){super.onPlace(s,l,p,old,moving);if(s.getBlock()!=old.getBlock())NativeNavigationTableAssemblies.queue(l,p);}
 @Override protected void neighborChanged(BlockState s,Level l,BlockPos p,Block b,BlockPos from,boolean moving){if(from.getY()==p.getY())NativeNavigationTableAssemblies.queue(l,p);}
 @Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState next,boolean moving){if(s.getBlock()!=next.getBlock()){if(!l.isClientSide&&!com.vandorlabs.neoforge.placement.NativeStationaryPlacement.mutating(l,p)&&!com.vandorlabs.neoforge.gear.NativeGearHolds.publicationAdmitted(l,p)&&!com.vandorlabs.neoforge.transfer.NativeTransferHolds.publicationAdmitted(l,p)&&l.getBlockEntity(p) instanceof NativeNavigationTableEntity t){t.ejectModule();t.ejectChip();}for(var d:Direction.Plane.HORIZONTAL)NativeNavigationTableAssemblies.queue(l,p.relative(d));}super.onRemove(s,l,p,next,moving);}
 private InteractionResult use(Player player,Level level,BlockPos pos,BlockHitResult hit,ItemStack stack){if(!(level.getBlockEntity(pos) instanceof NativeNavigationTableEntity t)||t.inert()||!NativeConfigurationAccess.canEditDialog(player,level,pos,hit.getDirection()))return InteractionResult.FAIL;
  if(stack.is(com.vandorlabs.neoforge.VandorLabsBootstrap.CONFIGURIZER.get())||player.isShiftKeyDown()&&stack.isEmpty())return NativeNavigationTableBindings.open(player,level,pos)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.FAIL;
  double y=hit.getLocation().y-pos.getY();if(t.hasModuleBay()&&hit.getDirection()==t.moduleFacing()&&across(hit,pos,t.moduleFacing())>=.125&&across(hit,pos,t.moduleFacing())<=.875&&y>=.109375&&y<=.359375){if(level.isClientSide)return InteractionResult.SUCCESS;if(NativeNavigationTableHooks.TABLE.moduleItem(stack)){if(!t.installModule(stack))return InteractionResult.FAIL;if(!player.isCreative())stack.shrink(1);return InteractionResult.CONSUME;}if(stack.isEmpty()){give(player,t.takeModule());return InteractionResult.CONSUME;}}
  if(t.hasMount()&&hit.getDirection()==t.getBlockState().getValue(FACING)&&across(hit,pos,t.getBlockState().getValue(FACING))>=.3125&&across(hit,pos,t.getBlockState().getValue(FACING))<=.6875&&y>=(kind==NavigationLayout.Kind.FLAT?.46875:.09375)&&y<=(kind==NavigationLayout.Kind.FLAT?.84375:.46875)){if(level.isClientSide)return InteractionResult.SUCCESS;if(NativeNavigationTableHooks.TABLE.chipItem(stack)&&t.chipStack().isEmpty()){if(!t.setChip(stack.copyWithCount(1)))return InteractionResult.FAIL;if(!player.isCreative())stack.shrink(1);return InteractionResult.CONSUME;}if(stack.isEmpty()&&!t.chipStack().isEmpty()){var chip=t.chipStack().copy();if(!t.setChip(ItemStack.EMPTY))return InteractionResult.FAIL;give(player,chip);return InteractionResult.CONSUME;}}
  if(t.formed()&&t.selectedNavigation()){var p=t.plane();var eye=player.getEyePosition();var direction=player.getLookAngle();double denominator=direction.x*p.normal.x+direction.y*p.normal.y+direction.z*p.normal.z;if(denominator>=-1e-8)return InteractionResult.PASS;double distance=((p.bottomLeft.x-eye.x)*p.normal.x+(p.bottomLeft.y-eye.y)*p.normal.y+(p.bottomLeft.z-eye.z)*p.normal.z)/denominator;if(distance<0||distance>Math.min(8,player.blockInteractionRange()))return InteractionResult.PASS;var h=eye.add(direction.scale(distance));double x=h.x-p.bottomLeft.x,y0=h.y-p.bottomLeft.y,z=h.z-p.bottomLeft.z;double u=(x*p.basisU.x+y0*p.basisU.y+z*p.basisU.z)/p.widthBlocks,v=1-(x*p.basisV.x+y0*p.basisV.y+z*p.basisV.z)/p.heightBlocks;if(u>=0&&u<=1&&v>=0&&v<=1){int action=t.canvas().action(u,v);if(action!=0){if(level.isClientSide)NativeNavigationTableHooks.CLIENT_ACTION.accept(t.reader(),action);else NativeNavigationTableHooks.TABLE.action(player,t.reader(),action);return InteractionResult.sidedSuccess(level.isClientSide);}}}
  return NativeNavigationTableBindings.open(player,level,pos)?InteractionResult.sidedSuccess(level.isClientSide):InteractionResult.PASS;
 }

 @Override protected java.util.List<ItemStack> getDrops(BlockState state,net.minecraft.world.level.storage.loot.LootParams.Builder builder){var raw=builder.getOptionalParameter(net.minecraft.world.level.storage.loot.parameters.LootContextParams.BLOCK_ENTITY);if(raw instanceof NativeNavigationTableEntity t&&t.inert()){var recovery=new ItemStack(this);recovery.set(net.minecraft.core.component.DataComponents.BLOCK_ENTITY_DATA,net.minecraft.world.item.component.CustomData.of(t.saveWithFullMetadata(builder.getLevel().registryAccess())));return java.util.List.of(recovery);}return super.getDrops(state,builder);}
 private static double across(BlockHitResult hit,BlockPos pos,Direction face){return face.getAxis()==Direction.Axis.Z?hit.getLocation().x-pos.getX():hit.getLocation().z-pos.getZ();}
 private static void give(Player p,ItemStack stack){if(!stack.isEmpty()&&!p.getInventory().add(stack))p.drop(stack,false);}
 @Override protected ItemInteractionResult useItemOn(ItemStack stack,BlockState s,Level l,BlockPos p,Player actor,InteractionHand hand,BlockHitResult hit){if(hand!=InteractionHand.MAIN_HAND)return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;var result=use(actor,l,p,hit,stack);if(result==InteractionResult.FAIL)return ItemInteractionResult.FAIL;return result.consumesAction()?ItemInteractionResult.sidedSuccess(l.isClientSide):ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;}
 @Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player actor,BlockHitResult hit){return use(actor,l,p,hit,ItemStack.EMPTY);}
}
